import os
import re
from taf.collectors.core.entities.collector import Collector
from taf.collectors.core.templates.dynamic_class_creation import Using


class DockerCollector(Using("tool_executor"), Using("file_getter"), Collector):
    """
          collect syslog from /tmp of docker container
    """

    def __init__(self, pod_name, namespace, **kwargs):

        self.target_file_name, new_kwargs = self.get_target_file_name(kwargs)
        super(DockerCollector, self).__init__(**new_kwargs)
        self._pod_name = pod_name
        self._namespace = namespace
        self._log_name = "{name}_docker_log".format(name=self._name)
        self._tmp_log_dir = "/tmp/docker_log/"+self._name

    def get_target_file_name(self, kwargs):
        target_file_name = kwargs.pop('target_file_name') if 'target_file_name' in kwargs.keys() else 'syslog.tgz'
        return target_file_name, kwargs

    def _setup(self):
        self._sudo_prefix = self._tool_executor.sudo_prefix()
        self._tool_executor.execute("rm -rf {log_dir}".format(log_dir=self._tmp_log_dir))
        self._tool_executor.execute("mkdir -p {log_dir}".format(log_dir=self._tmp_log_dir))
        self._docker_ids = {}
        self._get_docker_ids()

    def _teardown(self):
        self._tool_executor.execute("rm -rf {log_dir}".format(log_dir=self._tmp_log_dir))

    def _get_filter_dict(self):
        filter_dict = {}
        for c_name in self._containers:
            filter_dict.update({c_name: "{container}_{pod_name}_{namespace}".format(
                container=c_name, pod_name=self._pod_name, namespace=self._namespace)})
        return filter_dict

    def _get_docker_ids(self):
        filters = self._get_filter_dict()
        for c_name in filters:
            cmd = "{sudo_prefix}docker ps -aq --filter name={filter_str}".format(
                sudo_prefix=self._sudo_prefix, filter_str=filters[c_name])
            output = self._tool_executor.execute(cmd, use_tty=True)
            ids = re.findall(r"([a-z0-9]{12})", output.decode())
            for id in ids:
                self._docker_ids[id] = c_name

    def _get_log_files(self):
        tgz_log_list = []
        for docker_id in self._docker_ids:
            sub_log_name = "{log_name}_{container}".format(log_name=self._log_name,
                                                           container=self._docker_ids[docker_id])
            log_path = os.path.join(self._tmp_log_dir, sub_log_name)
            tgz_log_path = log_path + ".tgz"
            self._tool_executor.execute("{sudo_prefix}docker cp {docker_id}:/tmp {log_path}".format(
                sudo_prefix=self._sudo_prefix, docker_id=docker_id, log_path=log_path), use_tty=True)
            self._tool_executor.execute("{sudo_prefix}chown -R $(id -u):$(id -g) {log_path}".format(
                sudo_prefix=self._sudo_prefix, log_path=log_path), use_tty=True)
            self._tool_executor.execute("cd {tmp_log_dir};{sudo_prefix}tar czf {sub_log_tgz} {sub_log_name}".format(
                tmp_log_dir=self._tmp_log_dir, sudo_prefix=self._sudo_prefix, sub_log_tgz=sub_log_name + ".tgz",
                sub_log_name=sub_log_name), use_tty=True)
            self._tool_executor.execute("{sudo_prefix}chown -R $(id -u):$(id -g) {tgz_log_path}".format(
                sudo_prefix=self._sudo_prefix, tgz_log_path=tgz_log_path), use_tty=True)
            tgz_log_list.append(sub_log_name + ".tgz")

        all_tgz = " ".join(tgz_log_list)
        cmd = "cd {tmp_log_dir};{sudo_prefix}tar czf {target_file_name} {all_tgz}".format(
            tmp_log_dir=self._tmp_log_dir, sudo_prefix=self._sudo_prefix, target_file_name=self.target_file_name,
            all_tgz=all_tgz)
        self._tool_executor.execute(cmd, use_tty=True)

    def _collect(self, target_dir):
        self._get_log_files()
        target_file_path = self._tmp_log_dir + '/' + self.target_file_name
        self._file_getter.get_file(source_path=target_file_path,
                                   target_path="{target_dir}/{name}".format(target_dir=target_dir,
                                                                            name=self.target_file_name))


class ContainerDockerCollector(DockerCollector):
    def __init__(self, container, **kwargs):
        super(ContainerDockerCollector, self).__init__(**kwargs)
        self._containers = [container]


class PodDockerCollector(DockerCollector):
    def __init__(self, **kwargs):
        super(PodDockerCollector, self).__init__(**kwargs)
        self._sudo_prefix = self._tool_executor.sudo_prefix()
        self._containers = self._get_all_containers_of_pod()

    def _get_all_containers_of_pod(self):
        cmd = "{sudo_prefix}docker ps | tail -n +2 | perl -lanE'say$F[-1]' | ns={namespace} pod={pod_name} " \
              "perl -F_ -lanE'say $F[1] if $F[3] eq $ENV{{ns}} && $F[2] eq $ENV{{pod}} && $F[1] ne \"POD\"'" \
            .format(sudo_prefix=self._sudo_prefix, namespace=self._namespace, pod_name=self._pod_name)
        output = self._tool_executor.execute(cmd, use_tty=True)
        containers = output.decode().split(':')[1].split()
        return containers
